"""Environment repair challenge: do not edit this file."""
from __future__ import annotations

import json
from pathlib import Path

import httpx
from jinja2 import Environment, StrictUndefined
from pydantic import BaseModel, Field


DATA_FILE = Path(__file__).resolve().parent / "data" / "participants.json"
EXPECTED = "REPORT[Ada:95 | Grace:88 | Linus:81]"


class Participant(BaseModel):
    name: str
    score: int = Field(ge=0, le=100)


def mock_backend(request: httpx.Request) -> httpx.Response:
    """Serve fixed local test data; no internet connection is required."""
    if request.url.path != "/participants":
        return httpx.Response(404, json={"detail": "not found"})
    records = json.loads(DATA_FILE.read_text(encoding="utf-8"))
    return httpx.Response(200, json=records)


def main() -> None:
    transport = httpx.MockTransport(mock_backend)
    # This call follows the HTTPX 0.27.x interface.
    with httpx.Client(transport=transport, proxies=None, trust_env=False) as client:
        response = client.get("https://example.invalid/participants")
        response.raise_for_status()
        payload = response.json()

    participants = [Participant.model_validate(item) for item in payload]
    participants.sort(key=lambda item: item.score, reverse=True)
    rows = [f"{item.name}:{item.score}" for item in participants]

    template = Environment(undefined=StrictUndefined).from_string(
        "REPORT[{{ rows | join(' | ') }}]"
    )
    result = template.render(rows=rows)
    if result != EXPECTED:
        raise AssertionError(f"Unexpected report output: {result!r}")

    print("complete")


if __name__ == "__main__":
    main()
